using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageTargetGapTests
{
    private const string AttributeName = "System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverageAttribute";

    private const string Source = """
        using MessagePack;

        namespace TestNs
        {
            [GeneratedMessagePackResolver]
            public partial class MyResolver { }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)] public int A { get; set; }
            }
        }
        """;

    private const string SourceWithUserAttribute = """
        using System.Diagnostics.CodeAnalysis;
        using MessagePack;

        namespace TestNs
        {
            [ExcludeFromCodeCoverage]
            [GeneratedMessagePackResolver]
            public partial class MyResolver { }

            [MessagePackObject]
            public class IntKeyed
            {
                [Key(0)] public int A { get; set; }
            }
        }
        """;

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task AttributeIsEmittedWhenTargetSymbolDefined(string symbol)
    {
        var (output, trees) = await RunGeneratorAsync(Source, symbol);
        Assert.NotEmpty(trees);
        var types = new List<INamedTypeSymbol>();
        foreach (SyntaxTree tree in trees)
        {
            SyntaxTree inOutput = output.SyntaxTrees.First(t => t.FilePath == tree.FilePath);
            SemanticModel model = output.GetSemanticModel(inOutput);
            foreach (TypeDeclarationSyntax decl in inOutput.GetRoot().DescendantNodes().OfType<TypeDeclarationSyntax>())
            {
                if (model.GetDeclaredSymbol(decl) is INamedTypeSymbol s)
                {
                    types.Add(s);
                }
            }
        }

        Assert.NotEmpty(types);
        string[] notExcluded = types.Where(t => !IsExcluded(t)).Select(t => t.ToDisplayString()).Distinct().ToArray();
        Assert.True(notExcluded.Length == 0, "With " + symbol + " defined, generated types lack [ExcludeFromCodeCoverage]: " + string.Join(", ", notExcluded));
    }

    [Fact]
    public async Task UserExcludeFromCodeCoverageOnResolverStillCompiles()
    {
        var (output, _) = await RunGeneratorAsync(SourceWithUserAttribute);
        string[] errors = output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).Select(d => d.ToString()).ToArray();
        Assert.True(errors.Length == 0, string.Join(Environment.NewLine, errors));
    }

    private static bool IsExcluded(INamedTypeSymbol? type)
    {
        for (; type is not null; type = type.ContainingType)
        {
            if (type.GetAttributes().Any(a => a.AttributeClass?.ToDisplayString() == AttributeName))
            {
                return true;
            }
        }

        return false;
    }

    private static async Task<(Compilation Output, ImmutableArray<SyntaxTree> Trees)> RunGeneratorAsync(string source, params string[] symbols)
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.CSharp12, preprocessorSymbols: symbols);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> references = Enumerable.Concat<MetadataReference>(framework, ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsTargetGapAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);
        return (output, driver.GetRunResult().GeneratedTrees);
    }
}
